 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, add, sub, mul, fract, texture, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, SRGBColorSpace } = THREE;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const root = new Group();
  root.userData.handlers = {};

  const disposables = [];
  const timelines = [];
  const primitiveCleanups = [];

  // -- Backdrop: engineered vertical gradient with subtle grain
  const bgGeo = new PlaneGeometry(7, 6, 2, 2);
  const vUv = uv();
  const gradient = mix(
    vec3(color(colors.ink)),
    vec3(color(colors.surface)),
    smoothstep(0.0, 1.0, vUv.y)
  );
  const hashIndex = add(mul(vUv.x, 12.9898), mul(vUv.y, 78.233));
  const hash = fract(mul(hashIndex, 43758.5453));
  const grain = vec3(mul(sub(hash, 0.5), 0.025));
  const bgMat = new MeshBasicNodeMaterial({
    colorNode: vec4(add(gradient, grain), 1.0),
    side: THREE.DoubleSide
  });
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.z = -2.5;
  root.add(bg);
  disposables.push(bgGeo, bgMat);

  // -- Machined-metal label card
  const cardW = 1.28;
  const cardH = 0.8;
  const cardGeo = new PlaneGeometry(cardW, cardH, 1, 1);
  const metalMat = new MeshBasicNodeMaterial({
    colorNode: vec3(color(colors.paper))
  });
  const card = new Mesh(cardGeo, metalMat);
  root.add(card);
  disposables.push(cardGeo, metalMat);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (tex && tex.isTexture) {
        tex.colorSpace = SRGBColorSpace;
        tex.needsUpdate = true;
        metalMat.colorNode = texture(tex);
        metalMat.needsUpdate = true;
        root.userData.textures = root.userData.textures ?? [];
        root.userData.textures.push(tex);
      }
    });
  }

  // -- Text backing strip for contrast
  const stripeW = cardW * 0.84;
  const stripeH = 0.34;
  const stripeGeo = new PlaneGeometry(stripeW, stripeH, 1, 1);
  const stripeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.ink),
    transparent: true,
    opacity: 0.92
  });
  const stripe = new Mesh(stripeGeo, stripeMat);
  stripe.position.z = 0.006;
  root.add(stripe);
  disposables.push(stripeGeo, stripeMat);

  // -- Accent rule (<=10% of frame)
  const ruleGeo = new PlaneGeometry(stripeW * 0.55, 0.015, 1, 1);
  const ruleMat = new MeshBasicNodeMaterial({ color: new Color(colors.accent) });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(0, -stripeH * 0.28, 0.007);
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // -- Label text
  const textItems = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of textItems) {
    if (!item.text) continue;
    const px = item.typography?.fontSize ?? 39;
    const role = item.role ?? 'headline';
    const sceneSize = Math.max(0.05, px * 0.005);
    const textAlign = item.alignment ?? 'center';
    const textColor = role === 'caption' ? colors.paper : colors.paper;

    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: sceneSize,
      color: textColor,
      align: textAlign
    });
    textObj.position.z = 0.012;
    root.add(textObj);
  }

  // -- Static load entrance
  const entrance = gsap.timeline();
  root.scale.set(0.96, 0.96, 0.96);
  root.position.y -= 0.15;
  entrance.to(root.position, {
    y: root.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out'
  });
  entrance.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.7,
    ease: 'power3.out'
  }, '<');
  timelines.push(entrance);

  // -- Apply cinematic primitives
  for (const primitive of (config.cinematicPrimitives ?? [])) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params ?? {});
      if (result?.timeline) timelines.push(result.timeline);
      if (typeof result?.cleanup === 'function') primitiveCleanups.push(result.cleanup);
    }
  }

  root.userData.cleanup = () => {
    timelines.forEach((tl) => { if (tl) tl.kill(); });
    primitiveCleanups.forEach((fn) => { try { fn(); } catch {} });

    while (root.children.length) {
      const child = root.children[0];
      root.remove(child);
    }

    if (root.userData.textures) {
      root.userData.textures.forEach((tex) => { if (tex && tex.isTexture) tex.dispose(); });
    }

    disposables.forEach((obj) => {
      if (obj && obj.isBufferGeometry) obj.dispose();
      if (obj && obj.isMaterial) obj.dispose();
    });
  };

  return root;
}
